final class Loop {
    private var prev: CFTimeInterval = 0, lag: Double = 0
    private let dt = 1.0 / 60.0
    func start() {
        let link = CADisplayLink(target: self, selector: #selector(step(_:)))
        link.add(to: .main, forMode: .common)     // .common keeps firing during scroll
    }
    @objc private func step(_ link: CADisplayLink) {
        if prev != 0 { lag += link.timestamp - prev }
        prev = link.timestamp; lag = min(lag, 0.25)       // clamp
        while lag >= dt { world.step(dt); lag -= dt }
        render(lag / dt)
    }
}

